namespace Ordering;

/// <summary>Imports orders from a batch of delimited rows.</summary>
public sealed class OrderImporter
{
    private readonly OrderRepository _repository;

    public OrderImporter(OrderRepository repository) => _repository = repository;

    public IReadOnlyList<Order> ImportBatch(IEnumerable<string> rows)
    {
        var imported = new List<Order>();
        var seen = new HashSet<string>(StringComparer.Ordinal);

        foreach (var row in rows)
        {
            var parts = SplitValidRow(row);
            if (parts is null)
                continue;

            var reference = parts[1].Trim();
            if (reference.Length == 0 || !seen.Add(reference))
                continue;

            var order = CreateOrder(parts[0].Trim(), reference);
            if (order is null)
                continue;

            AddOrderLines(order, parts);
            if (order.Lines.Count == 0)
                continue;

            _repository.Add(order);
            imported.Add(order);
        }

        return imported;
    }

    private static string[]? SplitValidRow(string row)
    {
        if (string.IsNullOrWhiteSpace(row))
            return null;

        var parts = row.Split(',');
        return parts.Length >= 4 ? parts : null;
    }

    private static Order? CreateOrder(string recordType, string reference)
    {
        var channel = recordType switch
        {
            "H" or "ORDER" => OrderChannel.Web,
            "M" => OrderChannel.Marketplace,
            _ => (OrderChannel?)null
        };

        return channel is null
            ? null
            : new Order { Reference = reference, Channel = channel.Value };
    }

    private static void AddOrderLines(Order order, string[] parts)
    {
        for (var i = 2; i + 1 < parts.Length; i += 2)
        {
            var sku = parts[i].Trim();
            if (sku.Length == 0 ||
                !int.TryParse(parts[i + 1], out var quantity) ||
                quantity <= 0)
            {
                continue;
            }

            order.Lines.Add(new OrderLine
            {
                Sku = sku,
                Quantity = quantity,
                UnitPrice = GetUnitPrice(sku, quantity)
            });
        }
    }

    private static decimal GetUnitPrice(string sku, int quantity)
    {
        if (sku.StartsWith("PRM", StringComparison.Ordinal) && quantity > 10)
            return 9.99m;

        return sku.StartsWith("STD", StringComparison.Ordinal) ? 4.99m : 0m;
    }
}
